questionvariables.text:
/* Radio options: static literal values, sentence displays. Exactly one is true. */
ta1: [[optA, false, "A. If any vertical line meets the graph at more than one point, the graph is a one-to-one function."],
 [optB, false, "B. If every vertical line meets the graph at most once, the relation is not a function."],
 [optC, true, "C. If any vertical line meets the graph at more than one point, the graph is not a function."],
 [optD, false, "D. If any vertical line meets the graph at exactly one point, the graph is a many-to-one function."]];
tac1: first(mcq_correct(ta1));
